SELECT CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, CASE WHEN o.shipping_fee >= 38 THEN 'high' WHEN o.shipping_fee >= 7 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, SUM(oi.unit_price) AS total_unit_price FROM order_items oi INNER JOIN orders o ON oi.order_id = o.id GROUP BY CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN o.shipping_fee >= 38 THEN 'high' WHEN o.shipping_fee >= 7 THEN 'mid' ELSE 'low' END ORDER BY order_cohort;
